'use client';

import { useEffect, useRef, useState } from 'react';

import {
  type AutoplayStep,
  typingSteps,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import {
  hold,
  PRESS_LEAD_MS,
  spokenUnless,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { Wash } from '@/registry/ndeko/ui/wash';

import { AvatarStack } from './avatar-stack';
import { DEMO_EMAIL, HERO, type Status } from './data';
import { EmailForm } from './email-form';
import { INITIAL_STACK, type Stack, withDemoJoin, withJoin } from './stack';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const JOIN_DELAY_MS = 900;

const NEW_MEMBER_EVERY_MS = 2400;

function emailErrorOf(value: string) {
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    return HERO.emptyError;
  }
  const isEmailShaped = EMAIL_PATTERN.test(trimmed);
  if (!isEmailShaped) {
    return HERO.shapeError;
  }
  return null;
}

function announcementOf(error: string | null, status: Status) {
  if (error !== null) {
    return error;
  }
  if (status === 'done') {
    return HERO.doneAnnouncement;
  }
  return '';
}

export default function Heroes10() {
  const [email, setEmail] = useState('');
  const [status, setStatus] = useState<Status>('idle');
  const [error, setError] = useState<string | null>(null);
  const [hasTriedSubmit, setHasTriedSubmit] = useState(false);
  const [stack, setStack] = useState<Stack>(INITIAL_STACK);
  const inputRef = useRef<HTMLInputElement>(null);
  const { pressed, press } = usePress<'join'>();

  useEffect(() => {
    if (status !== 'busy') {
      return;
    }
    const timeout = window.setTimeout(() => {
      setStatus('done');
      setStack((current) => withJoin(current, email));
    }, JOIN_DELAY_MS);
    return () => window.clearTimeout(timeout);
  }, [status, email]);

  function changeEmail(value: string) {
    setEmail(value);
    if (hasTriedSubmit) {
      setError(emailErrorOf(value));
    }
  }

  function submit() {
    const nextError = emailErrorOf(email);
    setHasTriedSubmit(true);
    setError(nextError);
    if (nextError !== null) {
      inputRef.current?.focus();
      return;
    }
    setStatus('busy');
  }

  function startOver() {
    setEmail('');
    setStatus('idle');
    setError(null);
    setHasTriedSubmit(false);
  }

  function startAnother() {
    startOver();
    inputRef.current?.focus();
  }

  function addDemoMember() {
    setStack(withDemoJoin);
  }

  const steps: AutoplayStep[] = [
    { after: NEW_MEMBER_EVERY_MS, run: addDemoMember },
    { after: NEW_MEMBER_EVERY_MS, run: addDemoMember },
    ...typingSteps(DEMO_EMAIL, setEmail, { startAfter: 700, characterMs: 55 }),
    { after: 500, run: () => press('join') },
    { after: PRESS_LEAD_MS, run: submit },
    { after: NEW_MEMBER_EVERY_MS, run: addDemoMember },
    { after: NEW_MEMBER_EVERY_MS, run: hold },
  ];
  const { ref, isAutoplaying } = useAutoplay(steps, {
    loopAfter: 600,
    onReset: startOver,
  });
  const hasJoined = stack.count > INITIAL_STACK.count;
  const announcement = announcementOf(error, status);
  const message = spokenUnless(isAutoplaying, announcement);

  useKeptHeight(ref);

  return (
    <section className='@container'>
      <div ref={ref} className='relative isolate'>
        <Wash className='h-[28rem]' />
        <div className='mx-auto flex max-w-3xl flex-col items-center gap-6 px-4 py-16 text-center @2xl:px-6 @2xl:py-24'>
          <p className='text-primary-ink text-sm font-medium'>{HERO.eyebrow}</p>
          <h1 className='text-4xl font-semibold text-balance @2xl:text-5xl'>
            {HERO.title}
          </h1>
          <p className='text-muted-foreground max-w-xl text-base text-pretty'>
            {HERO.description}
          </p>
          <EmailForm
            email={email}
            status={status}
            error={error}
            isPressed={pressed === 'join'}
            inputRef={inputRef}
            onEmailChange={changeEmail}
            onSubmit={submit}
            onUseAnother={startAnother}
          />
          <AvatarStack stack={stack} hasJoined={hasJoined} />
          <LiveRegion message={message} />
        </div>
      </div>
    </section>
  );
}

'use client';

import type { ChangeEvent, FormEvent, RefObject } from 'react';

import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { Field, FieldError, FieldLabel } from '@/registry/ndeko/ui/field';
import { Input } from '@/registry/ndeko/ui/input';
import { MorphButton } from '@/registry/ndeko/ui/morph-button';

import { BUTTON_LABELS, HERO, type Status } from './data';

function noteKeyOf(isDone: boolean) {
  if (isDone) {
    return 'done';
  }
  return 'note';
}

type EmailFormProps = {
  email: string;
  status: Status;
  error: string | null;
  isPressed: boolean;
  inputRef: RefObject<HTMLInputElement | null>;
  onEmailChange: (value: string) => void;
  onSubmit: () => void;
  onUseAnother: () => void;
};

export function EmailForm({
  email,
  status,
  error,
  isPressed,
  inputRef,
  onEmailChange,
  onSubmit,
  onUseAnother,
}: EmailFormProps) {
  const hasError = error !== null;
  const isIdle = status === 'idle';
  const isDone = status === 'done';
  const noteKey = noteKeyOf(isDone);

  function change(event: ChangeEvent<HTMLInputElement>) {
    onEmailChange(event.target.value);
  }

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit();
  }

  return (
    <form
      noValidate
      onSubmit={submit}
      className='flex w-full max-w-md flex-col gap-2'
    >
      <Field invalid={hasError}>
        <FieldLabel className='sr-only'>{HERO.emailLabel}</FieldLabel>
        <div className='flex flex-col gap-2 @md:flex-row'>
          <Input
            ref={inputRef}
            type='email'
            name='email'
            size='lg'
            autoComplete='email'
            placeholder={HERO.emailPlaceholder}
            value={email}
            onChange={change}
            readOnly={!isIdle}
          />
          <MorphButton
            type='submit'
            size='lg'
            state={status}
            labels={BUTTON_LABELS}
            className={pressedSolidOf(isPressed)}
          />
        </div>
        {hasError && <FieldError match>{error}</FieldError>}
      </Field>
      <Swap
        swapKey={noteKey}
        className='text-muted-foreground min-h-5 justify-center text-xs'
      >
        {!isDone && <span>{HERO.note}</span>}
        {isDone && (
          <span className='flex flex-wrap items-center justify-center gap-x-2'>
            <span>{HERO.doneNote}</span>
            <Button
              type='button'
              variant='link'
              onClick={onUseAnother}
              className='h-auto p-0 text-xs'
            >
              {HERO.useAnother}
            </Button>
          </span>
        )}
      </Swap>
    </form>
  );
}

import type { CSSProperties } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';

import { HERO, VISIBLE_COUNT } from './data';
import type { Stack } from './stack';

type SlotStyle = CSSProperties & { '--slot': number };

function slotStyleOf(slot: number) {
  const style: SlotStyle = { '--slot': slot };
  return style;
}

/** The newest avatar slides in from beside the stack; the first ones are simply there. */
function arrivalClassOf(isNewest: boolean, hasJoined: boolean) {
  const isArriving = isNewest && hasJoined;
  if (isArriving) {
    return 'starting:opacity-0 starting:translate-x-[calc((var(--slot)_-_1)*1.5rem)]';
  }
  return undefined;
}

function tuckClassOf(isTucked: boolean) {
  if (isTucked) {
    return 'opacity-0';
  }
  return 'opacity-100';
}

type AvatarStackProps = {
  stack: Stack;
  hasJoined: boolean;
};

/**
 * Avatars overlap in slots. Each one reads its slot from a custom property and its position
 * follows it with a transition, so a new member shifts the others along without any layout work.
 */
export function AvatarStack({ stack, hasJoined }: AvatarStackProps) {
  return (
    <div className='flex items-center gap-3'>
      <div className='flex items-center'>
        <div aria-hidden='true' className='relative h-9 w-24 shrink-0'>
          {stack.members.map((member, slot) => (
            <Avatar
              key={member.id}
              seed={member.name}
              style={slotStyleOf(slot)}
              className={cn(
                'outline-background absolute top-0 left-0 size-9 translate-x-[calc(var(--slot)*1.5rem)] outline-2 transition-[translate,opacity] duration-500 ease-(--ease-out-strong) motion-reduce:transition-none',
                tuckClassOf(slot >= VISIBLE_COUNT),
                arrivalClassOf(slot === 0, hasJoined)
              )}
            />
          ))}
        </div>
        <span className='bg-card hairline-ring ring-border outline-background relative z-10 inline-flex h-9 items-center rounded-full px-3 text-[13px] font-medium outline-2'>
          <MotionNumber value={stack.count} className='tabular-nums' />
        </span>
      </div>
      <div className='flex flex-col items-start text-start'>
        <p className='text-[13px]'>{HERO.countCaption}</p>
        <p className='text-muted-foreground text-xs'>{HERO.countNote}</p>
      </div>
    </div>
  );
}

import {
  BASE_COUNT,
  DEMO_NAMES,
  INITIAL_NAMES,
  KEPT_COUNT,
  type Member,
} from './data';

export type Stack = {
  /** Newest first. */
  members: Member[];
  count: number;
  nextDemo: number;
};

const INITIAL_MEMBERS: Member[] = INITIAL_NAMES.map((name, index) => ({
  id: index,
  name,
}));

export const INITIAL_STACK: Stack = {
  members: INITIAL_MEMBERS,
  count: BASE_COUNT,
  nextDemo: 0,
};

export function withJoin(stack: Stack, name: string): Stack {
  const count = stack.count + 1;
  const member: Member = { id: count, name };
  const members = [member, ...stack.members].slice(0, KEPT_COUNT);
  return { ...stack, members, count };
}

export function withDemoJoin(stack: Stack): Stack {
  const position = stack.nextDemo % DEMO_NAMES.length;
  const name = DEMO_NAMES[position];
  const joined = withJoin(stack, name);
  return { ...joined, nextDemo: stack.nextDemo + 1 };
}

export type Member = {
  id: number;
  name: string;
};

export type Status = 'idle' | 'busy' | 'done';

export const HERO = {
  eyebrow: 'Opening in small groups',
  title: 'A calmer inbox for people who work alone',
  description:
    'Your mail sorts itself into what needs a reply today and what can wait. We let people in a few at a time, in the order they joined.',
  emailLabel: 'Email address',
  emailPlaceholder: 'you@example.com',
  emptyError: 'Enter your email address to join the waitlist',
  shapeError: 'Check the address, it should look like name@example.com',
  note: 'One email when a seat opens, nothing else',
  doneNote: 'We will email you when a seat opens',
  doneAnnouncement: 'You are on the list. We will email you when a seat opens.',
  useAnother: 'Use another address',
  countCaption: 'on the waitlist',
  countNote: 'Illustrative count',
};

export const BUTTON_LABELS: Record<Status, string> = {
  idle: 'Join the waitlist',
  busy: 'Joining',
  done: 'You are on the list',
};

export const DEMO_EMAIL = 'amara.n@example.com';

export const INITIAL_NAMES = [
  'Noor Haddad',
  'Patrick Kabongo',
  'Lea Fontaine',
  'Joseph Kasongo',
  'Ines Moreau',
];

export const DEMO_NAMES = [
  'Tomas Rivera',
  'Chantal Mbuyi',
  'Kwame Boateng',
  'Sofia Lindqvist',
  'Daniel Okoye',
  'Mireille Tshimanga',
  'Hana Sato',
  'Rafael Duarte',
  'Grace Ilunga',
  'Mateo Bianchi',
];

export const BASE_COUNT = 2418;

/** Avatars that show, and one more tucked under the counter while it leaves. */
export const VISIBLE_COUNT = 4;

export const KEPT_COUNT = VISIBLE_COUNT + 1;
